#include <iostream>
#include <typeinfo>
class Empty {};
class A {
  int arr[0]; // Zero-sized array
};
class B : public Empty {};
class C : public A, public B {};
int main() {
  std::cout << "sizeof(A): " << sizeof(A) << std::endl;
  std::cout << "sizeof(B): " << sizeof(B) << std::endl;
  std::cout << "sizeof(C): " << sizeof(C) << std::endl;
  //Observe the result and compare it with compiler optimization settings.
  //Compiler may produce different results with/without optimization(-O0,-O1,-O2,-O3).
  return 0;
}
